insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 1, 'What are the four jobs of drilling mud?', '["Lubricate, cool, clean and seal.", "Carry cuttings, hold the hole up, clean and cool the bit, and not break the formation.", "Carry cuttings, transmit power to the mud motor, cool the bit and provide the hydrostatic head at the shoe.", "Suspend barite, carry cuttings, transmit measurement-while-drilling telemetry and cool the bottom hole assembly."]'::jsonb, 1, 'The fourth is in direct opposition to the other three: more flow and more density help the first three and hurt the fourth.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 2, 'Which quantity ties the four jobs together?', '["The pump pressure at the standpipe.", "The flow rate, since every one of the four jobs depends on it directly and none of them depends on anything else.", "The equivalent circulating density, which is what the formation actually experiences.", "The mud weight, which is the only input that appears in all four of the constraints simultaneously."]'::jsonb, 2, 'Almost everything in the course is about what moves it, and it is the number compared against the fracture gradient.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 3, 'What does this course NOT compute?', '["Temperature, compressibility, gas in the annulus, and cuttings beds.", "Pressure loss in the annulus.", "The equivalent circulating density, which requires a fracture gradient that comes from the geomechanics course.", "Surge and swab pressures, which need a transient model rather than the steady state this engine implements."]'::jsonb, 0, 'It does compute surge and swab, steadily. The four listed are named properly in the Expert tier''s scope statement.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 4, 'How many fixtures does the course run, and how are they arranged?', '["Two, one well and one mud each.", "Four independent cases with different wells, strings, muds and bits, chosen to span the range of drilling conditions.", "Five, matching the five wells the torque and drag course uses, with one mud shared across all of them.", "Four: two wells crossed with two muds."]'::jsonb, 3, 'Every other input is shared, which is what makes a difference in the answer attributable to one change.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 5, 'Which two dial readings does a Fann viscometer give at low shear rate?', '["6 rpm and 3 rpm.", "100 rpm and 200 rpm.", "The gel strengths at 10 seconds and 10 minutes, which are measured after a period at rest rather than at a speed.", "There are none: the instrument only reads at 600, 300, 200 and 100 rpm."]'::jsonb, 0, 'The gel strengths are a different measurement on the same instrument, and this engine does not use them.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 6, 'Why is the collars'' bore important in this course and not in the torque and drag one?', '["Because the collars are the heaviest component.", "Because pressure loss depends on the inside diameter and torque and drag does not.", "Because the collars are in the tightest annulus, which is where the annular pressure loss concentrates.", "Because the collars carry no tool joints, so their outside diameter is the contact surface in both courses."]'::jsonb, 1, 'At 0.05715 m the collars'' bore carries roughly four times the drill pipe''s velocity, and velocity enters squared.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 7, 'What does buildFlowElements return?', '["A single pressure loss for the whole path.", "The velocity and Reynolds number in each section, from which the friction factors are then computed separately.", "A pipe element list, an annulus element list, the bit depth and a coverage flag.", "The survey resampled onto a fine grid, with the string composition looked up at every point along it."]'::jsonb, 2, 'It is the structure the whole calculation runs on, and it is built once before any pressure is computed.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 8, 'What characteristic dimension does an annulus element use?', '["The hole diameter alone.", "The mean of the two diameters, which is the equivalent circular pipe with the same cross-sectional area.", "Four times the flow area divided by the wetted perimeter, which for concentric circles is not the difference.", "The hole diameter less the pipe''s outside diameter."]'::jsonb, 3, 'Four times the area over the wetted perimeter IS exactly the difference for concentric circles, which is why the two forms agree.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 9, 'Why do velocities differ everywhere in the flow path?', '["Because the areas differ and the flow rate is the same everywhere.", "Because the mud''s density varies with depth.", "Because the friction factor varies from element to element, which changes the effective velocity in each of them.", "Because the pump delivers a pulsating flow, so the instantaneous velocity is different in every element."]'::jsonb, 0, 'That is why the narrowest element has the highest velocity and why the worst cleaning is in the widest annulus.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 10, 'What does the geometry coverage warning mean?', '["The survey does not reach total depth.", "The hole geometry does not describe the whole string, and those annulus spans are skipped.", "The string extends below the casing shoe, which is normal and the warning can safely be ignored on any well.", "Two geometry sections overlap, so the engine chose one of them arbitrarily at each integration interval."]'::jsonb, 1, 'Skipped, not zero-friction: their length contributes nothing at all, so the annulus loss is understated by an unknown amount.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 11, 'Which decision needs both a hydraulics answer and a geomechanics one?', '["What pump the rig needs.", "What nozzles to run, which needs the fracture gradient in order to fix the split between the bit and the system.", "Whether the flow rate needed to clean the hole breaks the formation.", "How fast to trip, which is settled entirely by the surge and swab pressures this course computes."]'::jsonb, 2, 'The trip speed also needs a pore pressure and a fracture gradient. The pump and the nozzles are hydraulics alone.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 12, 'What is the pump pressure a property of?', '["The system: the string, the bit and the mud.", "The formation.", "The well''s true vertical depth, which sets the hydrostatic head the pump has to overcome to circulate.", "The flow rate alone, since every other input is fixed once the string is made up and run in the hole."]'::jsonb, 0, 'Change the formation and the pump pressure does not move. That is the opposite of the equivalent circulating density.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 13, 'What flow rates do the lessons run at?', '["0.010, 0.020 and 0.030 m3/s.", "A continuous sweep from 0.005 to 0.050 m3/s, from which any particular value can be read off the chart.", "Whatever rate the minimum flow solver returns for a transport ratio of 0.9 on each of the four cases.", "0.015, 0.025 and 0.035 m3/s."]'::jsonb, 3, 'The capstone runs at a rate that is not one of those three, which is how every graded number is one you have to produce.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 14, 'Why are the four jobs in conflict?', '["They are not in conflict.", "The fourth wants less flow and less density and the first three want more of both.", "Because the mud cannot be both dense enough to hold the hole up and thin enough to be pumped at a useful rate.", "Because carrying cuttings needs a high viscosity and cooling the bit needs a low one, and the two cannot both be met."]'::jsonb, 1, 'The viscosity conflict is real and is resolved by shear thinning. The density and rate conflict is not resolvable and is the whole course.'),
  ('hydraulics', 'beginner', 'module', 'm01-what-hydraulics-is-for', 15, 'What is the total flow area of the bit in this course?', '["It varies by case.", "0.0003 m2, which is the value the optimisation lesson uses to demonstrate the effect of tightening the nozzles.", "0.000461814 m2, shared by all four fixtures.", "It is not stated, because the bit pressure drop is supplied directly rather than computed from a nozzle area."]'::jsonb, 2, 'Sharing it across all four cases is what makes the pump pressures comparable between the two wells and the two muds.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 1, 'What does a Fann viscometer measure?', '["The torque on a cylinder spinning in mud, read as a dial deflection at a set speed.", "The mud''s density at surface.", "The pressure required to force mud through a capillary of known length and diameter at a set flow rate.", "The time a fixed volume of mud takes to drain through a standard orifice, which is the funnel viscosity."]'::jsonb, 0, 'Each rpm becomes a shear rate and each dial degree becomes a shear stress, so four readings become four points on a curve.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 2, 'What converts a dial degree to a shear stress?', '["The rotational speed in rpm.", "The mud''s density, since the torque on the cylinder depends on the weight of fluid it is dragging around with it.", "A geometry constant of 1.066 times the conversion from lbf per 100 ft2 to pascals.", "Nothing: the dial already reads in pascals on a modern instrument, so no conversion is needed at all."]'::jsonb, 2, 'It comes to 0.51040356094 Pa per degree, and the rate conversion is 1.70233 per second per rpm.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 3, 'What does the pair of low-rate readings tell you?', '["That the instrument is faulty.", "That the mud has a yield: the stress barely falls between 6 and 3 rpm.", "That the mud is Newtonian at low rates, since a constant stress with falling rate means a rising viscosity.", "That the mud has thixotropic gels, since the readings at low speed are dominated by the structure at rest."]'::jsonb, 1, 'The gels are a different measurement, taken after a period at rest. The yield is what suspends barite when the pumps are off.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 4, 'How does the power law fit?', '["A least-squares fit to all four readings.", "Three parameters to three readings, using the 6 rpm value to fix the yield stress the other two cannot supply.", "Two parameters to the 600 and 6 rpm readings, which span the widest range of shear rates available.", "Two parameters to the 600 and 300 rpm readings, exactly."]'::jsonb, 3, 'Two parameters and two readings means the fit is exact at those two and unconstrained everywhere else.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 5, 'What does the power law have no term for?', '["A yield stress: as the shear rate goes to zero the stress goes to zero.", "A shear-thinning exponent.", "A consistency index, which is why the model needs a second reading to fix the stress level at any given rate.", "The mud density, which has to be supplied separately to the pressure calculation rather than fitted."]'::jsonb, 0, 'A real mud does not do that, and the error is a factor of five at 3 rpm, which is in the range the annulus runs at.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 6, 'Which way does the power law''s low-rate error go?', '["It overstates it.", "It has no low-rate error, because the fit is exact at both readings and the model is a straight line on log axes.", "It UNDERSTATES the stress, so the annulus loss and the ECD come out low.", "It understates the stress at low rate and overstates it at high rate, so the two errors partly cancel."]'::jsonb, 2, 'Understating the equivalent circulating density is the unsafe direction, which is why the model choice matters.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 7, 'What two numbers does the Bingham model produce?', '["A consistency index and an exponent.", "A plastic viscosity and a yield point, both by subtraction from the two high-rate readings.", "A yield stress and a flow behaviour index, which together describe the curve from zero rate upward.", "A gel strength at 10 seconds and one at 10 minutes, which is what a mud engineer reports on a daily sheet."]'::jsonb, 1, 'PV and YP are the most widely used pair of rheology numbers in drilling, and both are computed by subtraction.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 8, 'A straight line extrapolated back to zero rate. What does that do to the annulus?', '["It understates it.", "It has no low-rate error, since the yield point is fitted directly to the intercept at zero shear rate.", "It overstates the stress at low rate and at high rate equally, because the fit is a straight line through both.", "It OVERSTATES the stress, so the ECD comes out high."]'::jsonb, 3, 'It is the safer direction and that is not a reason to prefer it. Both models are extrapolating a two-point fit.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 9, 'What is the Bingham yield point actually good for?', '["Tracking a mud over time: PV rises with solids and YP rises with treatment.", "Predicting the annular pressure loss.", "Computing the gel strength, since the yield point is the stress at zero rate and the gel is its value after rest.", "Fitting the Herschel-Bulkley model, which uses the Bingham yield point as its own yield stress parameter."]'::jsonb, 0, 'The two move independently and their movements are diagnostic, and that use does not depend on the model being right about the annulus.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 10, 'How does Herschel-Bulkley differ from the other two?', '["It has two parameters like the others.", "It is a least-squares fit to all four readings, which is why it misses each of them by a similar small amount.", "It has three parameters and uses a low-rate reading, so it reproduces none of them exactly.", "It is fitted to the gel strengths rather than to the flowing readings, which is why it captures the yield correctly."]'::jsonb, 2, 'Missing four points by a little is a better trade than hitting two exactly and missing two by a factor of two.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 11, 'Where do the three models agree, and where do they differ?', '["They agree everywhere within a percent.", "They agree at the high shear rates of the pipe and differ by a factor of ten in the annulus.", "They agree in the annulus, where the yield stress dominates, and differ in the pipe where the exponent matters.", "They differ everywhere, which is why the engine uses a different model for the pipe and for the annulus."]'::jsonb, 1, 'So the model choice barely moves the pump pressure and moves the number the formation feels, which is the opposite of the intuition.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 12, 'What is the apparent viscosity?', '["The plastic viscosity from the Bingham fit.", "The viscosity measured at 300 rpm, which by the instrument''s geometry is numerically equal to the dial reading.", "The consistency index K, which is the stress at a shear rate of one and therefore has viscosity units.", "The stress divided by the shear rate: the Newtonian viscosity that would give the same stress."]'::jsonb, 3, 'K has units of Pa.s^n rather than Pa.s, which is why quoting it without n is meaningless.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 13, 'What does the local power law method do?', '["Evaluates the Herschel-Bulkley model at each element''s shear rate to get a local n and K.", "Fits one n and K to the whole well.", "Averages the three fitted models, weighting each by how well it reproduced the four dial readings.", "Interpolates between the four dial readings directly, without fitting any model to them at all."]'::jsonb, 0, 'A single fitted n would be wrong nearly everywhere: the reported local n varies from about 0.10 to 0.77 across the shear range.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 14, 'Which mud in this course is the more shear thinning?', '["The heavy one, whose n is lower.", "They are equally shear thinning, since both are polymer muds and the exponent depends on the polymer type.", "The light one, whose power-law n is lower.", "It cannot be said from n alone, because the consistency index also affects how steeply the curve falls."]'::jsonb, 2, 'The light mud also has the higher K, which is not a contradiction: K is the stress at a rate of one and the two curves cross.'),
  ('hydraulics', 'beginner', 'module', 'm02-mud-rheology', 15, 'Which model does the engine use for every pressure calculation?', '["The power law, being the simplest.", "Herschel-Bulkley, through the local power law.", "Bingham, because its plastic viscosity and yield point are what a mud engineer actually reports on the rig.", "Whichever of the three reproduces the four dial readings with the smallest total residual on that mud."]'::jsonb, 1, 'It is the standard modern approach and it is what the goldens'' method specification names.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 1, 'What form does an element pressure loss take?', '["Density times gravity times height.", "Two f rho v squared L over d, with f the Fanning friction factor.", "The flow rate squared over twice the discharge coefficient squared times the area squared, which is the nozzle form.", "The apparent viscosity times the shear rate times the length, integrated over the element''s cross section."]'::jsonb, 1, 'Four inputs: velocity from geometry, density from the mud, length from the depth span, and the friction factor from the rheology.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 2, 'Why is the friction factor the whole problem?', '["Because it depends on the Reynolds number, which depends on the viscosity, which depends on the velocity.", "Because it is measured rather than computed.", "Because it varies with the pipe''s roughness, which is not known for a drilled hole and has to be assumed.", "Because it is different for every mud and has to be fitted to the four dial readings separately for each element."]'::jsonb, 0, 'For a Newtonian fluid the circularity is easy because the viscosity is a constant. For a shear-thinning one it is not.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 3, 'What is the laminar friction factor in a pipe and in an annulus?', '["Both 16 over Re.", "16 over Re and 32 over Re, the second being twice the first because an annulus has two walls rather than one.", "16 over Re and 24 over Re, both exact results for the geometry.", "Both fitted correlations, with the annulus value about half again the pipe value across the usable range."]'::jsonb, 2, 'The annulus has more wall per unit of flow area, so it costs more. Both are derived rather than fitted.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 4, 'What form does the turbulent friction factor take?', '["16 over Re, as in laminar flow.", "A constant, since in fully rough turbulent flow the friction factor stops depending on the Reynolds number at all.", "The Colebrook implicit form, solved iteratively for each element from the pipe''s relative roughness.", "A over Re to the b, with a and b functions of the local flow behaviour index."]'::jsonb, 3, 'It is the Bourgoyne form and it is an empirical correlation rather than a derivation, which is worth knowing when comparing packages.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 5, 'Where is the flow turbulent and where is it laminar in this course?', '["Turbulent inside the pipe, usually laminar or transitional in the annulus.", "Turbulent everywhere.", "Laminar inside the pipe, because the collars'' small bore raises the viscous forces relative to the inertial ones.", "It depends on the mud: the heavy mud is turbulent throughout and the light one is laminar throughout."]'::jsonb, 0, 'That difference is why the pump pressure rises much faster with flow rate than the equivalent circulating density does.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 6, 'Why does the engine blend between the two laws?', '["Because the two laws agree at the transition.", "Because a jump in the friction factor is unphysical and it breaks every solver in the course.", "Because the transition Reynolds number is not known precisely, so the blend covers the uncertainty in its value.", "Because the goldens were generated with a blend and the engine has to reproduce them exactly."]'::jsonb, 1, 'The solvers are bisections, which converge without continuity. What they would get wrong is the answer either side of a jump.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 7, 'How wide is the blend band?', '["80 Reynolds numbers.", "It is proportional to the local flow behaviour index, so a more shear-thinning mud has a wider transition band.", "800 Reynolds numbers above the critical value.", "It is not fixed: the engine widens it until the friction factor is continuous to within a stated tolerance."]'::jsonb, 2, 'It is a numerical convention rather than a physical measurement, and it is one of the four conventions in the method specification.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 8, 'Why does the blend width matter more than it looks?', '["Because it changes the pipe loss most.", "Because a wider band would make the calculation slower, since more elements need both friction factors computed.", "Because the goldens'' tolerance of 1e-6 cannot be met unless both implementations use exactly the same width.", "Because the annulus often sits inside the transition band, and the annulus sets the ECD."]'::jsonb, 3, 'So the part of the calculation with the most modelling convention in it is the part that produces the number the formation feels.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 9, 'Why is so much of this system''s pump pressure spent inside the string?', '["The collars'' bore is 0.05715 m, so the velocity there is high and velocity enters squared.", "Because the string is very long.", "Because the mud is thickest inside the pipe, where the shear rate is highest and the apparent viscosity peaks.", "Because the pipe elements are turbulent and the turbulent friction factor is much larger than the laminar one."]'::jsonb, 0, 'The apparent viscosity is LOWEST at high shear rate. The collars are 150 m of a 3000 m string and carry a large share of its loss.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 10, 'Does the pipe loss matter to the formation?', '["Yes, it adds to the ECD.", "Not directly: it is inside the string and the formation never sees it.", "Yes, because the pressure inside the pipe is transmitted through the steel to the annulus at the same depth.", "No, and it does not matter at all, since the pump is sized from the annulus loss rather than the total."]'::jsonb, 1, 'It matters indirectly, by capping the achievable flow rate through the pump''s limit, and a capped rate is a cleaning problem.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 11, 'Which annulus in this course is the tightest?', '["The one around the drill pipe in casing.", "The one around the heavy weight in open hole, since its tool joints are larger than the drill pipe''s body.", "The one around the collars in open hole.", "They are all the same, because the string is uniform and the hole size changes only at the shoe."]'::jsonb, 2, 'That is where the annular loss concentrates. The widest is the drill pipe in casing, and that is where the cleaning is worst.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 12, 'What is the annulus loss''s exponent against flow rate on the slant well?', '["Exactly 2, as at the bit.", "About 1.72, the same as the pipe, since both are computed with the same friction factor correlation.", "About 1.0, because the annular flow is laminar and laminar loss is proportional to velocity.", "About 0.75, which is below one."]'::jsonb, 3, 'Laminar loss is proportional to velocity to the power n for a power-law fluid, and n for these muds is around 0.7 to 0.8.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 13, 'What does the annulus''s sub-linear exponent mean in practice?', '["Doubling the flow rate raises the ECD by much less than double.", "Doubling the rate doubles the ECD.", "The annulus loss falls as the flow rate rises, because the mud thins faster than the velocity grows.", "The exponent is only valid in laminar flow, so it cannot be used to extrapolate to a higher rate at all."]'::jsonb, 0, 'It is the most encouraging result in the course: extra flow rate is cheap at the formation and expensive at the pump.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 14, 'What does the element form assume?', '["Nothing: it is an exact result.", "Laminar flow throughout, with the turbulent correlation applied as a correction where the Reynolds number is high.", "Fully developed flow, concentric geometry, no rotation and uniform properties.", "A Newtonian fluid, with the shear thinning applied afterwards as a multiplier on the computed pressure loss."]'::jsonb, 2, 'None of the four is exactly true in a real well, and the Expert tier names each one.'),
  ('hydraulics', 'beginner', 'module', 'm03-pressure-loss', 15, 'What does each element carry in the engine''s output besides a pressure?', '["A friction factor only.", "A regime label, so you can see where the answer is on solid ground.", "The local n and K, from which the friction factor can be recomputed by hand for any element of interest.", "The cuttings concentration in that element, which the hole cleaning calculation supplies to the pressure one."]'::jsonb, 1, 'Reading the labels tells you which elements are laminar, which are turbulent and which are inside the blend convention.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 1, 'What does the bit pressure calculation need from the nozzles?', '["The size of each nozzle separately.", "The number of nozzles and their spacing, since the jets interact under the bit and the losses are not independent.", "The total flow area, and nothing about how it is distributed.", "The nozzle length as well as the area, because the loss includes a friction term along the nozzle bore."]'::jsonb, 2, 'The nozzles are in parallel and the pressure drop across each is the same, so three equal nozzles and one big one are identical.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 2, 'Where does the nozzle distribution matter?', '["Bit balling and bottom hole cleaning, which the pressure equation does not see.", "In the pressure drop.", "In the equivalent circulating density, since an asymmetric jet arrangement biases the flow to one side of the annulus.", "Nowhere at all: a total flow area is a complete description of a bit for every purpose."]'::jsonb, 0, 'Which part of the cutting structure gets cleaned depends on where the jets point, and the pressure calculation is blind to it.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 3, 'What is the bit''s pressure drop proportional to?', '["The apparent viscosity times the rate.", "The density times the flow rate squared, over the flow area squared.", "The friction factor times the density times the velocity squared, which is the same form as every other element.", "The Reynolds number to a power that depends on the local flow behaviour index of the mud."]'::jsonb, 1, 'No viscosity, no length, no friction factor and no Reynolds number. It is an inertial loss rather than a friction one.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 4, 'Why is there no viscosity in the bit equation?', '["Because the mud is Newtonian at the bit.", "Because the nozzle is short enough that the friction along it is negligible compared with the entry loss.", "Because the discharge coefficient absorbs the viscosity, which is why it is fitted rather than derived.", "Because the loss is the energy spent accelerating mud into a jet and then throwing it away."]'::jsonb, 3, 'Inertia does not care how viscous the fluid is, which is why the bit exponent against flow rate is exactly two.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 5, 'What is the bit''s exponent against flow rate, and how exact is it?', '["Exactly two, to floating-point precision.", "About 1.7, like the pipe.", "About 2.1, slightly above two because the discharge coefficient falls as the jet velocity rises.", "It depends on the nozzle area, which sets how much of the pressure the bit takes at any given rate."]'::jsonb, 0, 'Compare the pipe at about 1.72 and the annulus at about 0.75. The steepest law wins as the rate rises.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 6, 'What happens to the bit''s SHARE of the pump pressure as the rate rises?', '["It falls.", "It stays constant, since all three losses are proportional to the same flow rate and the ratio is preserved.", "It rises, because its exponent is the steepest of the three.", "It rises and then falls, because the pipe becomes turbulent at high rate and overtakes the bit''s exponent."]'::jsonb, 2, 'That is the whole basis of bit hydraulics optimisation, and it means the bit is best served by pumping hard.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 7, 'What is the discharge coefficient, and what does it do?', '["1.0, since a nozzle is ideal.", "0.95, and it multiplies the jet velocity directly, so a five percent inefficiency costs five percent of the velocity.", "It is fitted per bit from the measured pump pressure, since nozzle geometry varies between manufacturers.", "0.95, an efficiency, and it appears squared in the denominator."]'::jsonb, 3, 'Squared in the denominator means a five percent inefficiency costs about ten percent more pressure than an ideal nozzle would.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 8, 'How does hydraulic power at the bit scale with flow rate?', '["As the square.", "As the cube, because the pressure goes as the square and the rate multiplies on top.", "Linearly, since power is pressure times rate and the pressure is fixed by the nozzle area rather than the rate.", "As the fourth power, because the jet velocity is proportional to the rate and it enters the power squared."]'::jsonb, 1, 'Impact force goes as the square, because both the rate and the jet velocity are proportional to it.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 9, 'Why are there two bit optimisation criteria rather than one?', '["Because different bits use different ones.", "Because power is the right criterion in hard rock and impact force in soft rock, and the two are never both relevant.", "Because maximising power and maximising impact force give different nozzle sizes.", "Because impact force is measured at the rig and power is computed, so the two describe the same thing differently."]'::jsonb, 2, 'The classical answers are around 65 percent of the pump pressure at the bit for power and around 48 for impact force.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 10, 'How firm are those two classical percentages?', '["They follow from an assumed exponent for the system loss, which is a property of the well.", "They are laws of nature.", "They are measured, from field trials that compared rate of penetration against the bit''s share of the pump pressure.", "They are API standards, so any bit programme that departs from them has to justify the departure."]'::jsonb, 0, 'Neither is a prediction of rate of penetration, and this course grades neither for that reason.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 11, 'What is the one lever that changes the pressure split without changing the flow rate?', '["The mud weight.", "The rate of penetration, which changes the cuttings load and therefore the annular pressure loss at a fixed rate.", "The rotary speed, which changes the shear rate in the annulus and therefore the apparent viscosity there.", "The nozzle total flow area."]'::jsonb, 3, 'It moves the bit pressure and leaves the pipe loss, the annulus loss and the equivalent circulating density exactly unchanged.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 12, 'What is the bit''s share on this course''s system at 0.025 m3/s?', '["About two thirds.", "Under a fifth, which is far below any classical optimum.", "About a half, which is between the impact force optimum of 48 percent and the power optimum of 65.", "It cannot be stated, because the split depends on the mud and the two muds give very different answers."]'::jsonb, 1, 'The collars'' bore is consuming so much pressure that there is little left for the bit, whatever the nozzles are.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 13, 'What does that finding mean for this well?', '["The nozzles should be tightened.", "The flow rate should be raised until the bit''s share reaches the classical optimum for hydraulic power.", "The bit hydraulics are limited by the string, not by the nozzle choice.", "The mud should be thinned, since a thinner mud lowers the pipe loss and frees pressure for the bit."]'::jsonb, 2, 'Tightening the nozzles to reach an optimal share would push the pump pressure far beyond anything a rig would supply.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 14, 'What does a sudden rise in standpipe pressure with no other change suggest?', '["A plugged nozzle, which reduces the total flow area.", "A washout in the string.", "A pack-off in the annulus, which is the only thing that can raise the pressure without changing the flow rate.", "A thickening mud, since the pipe loss is proportional to the apparent viscosity at high shear rate."]'::jsonb, 0, 'A pack-off also raises it, and it raises the torque as well. A washout LOWERS the pressure, by giving the mud a shortcut.'),
  ('hydraulics', 'beginner', 'module', 'm04-the-bit', 15, 'Which of these does the bit calculation NOT predict?', '["The pressure drop across the bit.", "The jet velocity, which follows from the pressure drop and the discharge coefficient by a rearrangement.", "The hydraulic power delivered at the bit, which is the pressure drop multiplied by the flow rate.", "The rate of penetration."]'::jsonb, 3, 'Nor bit balling, nozzle erosion or whether the jets still have energy when they reach the rock.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 1, 'What does the pump pressure equal?', '["The hydrostatic head at total depth.", "The pipe loss plus the bit loss plus the annulus loss, plus any surface loss.", "The largest of the three losses, since they are in parallel and the flow takes the path of least resistance.", "The annulus loss alone, since the other two are inside the string and are contained by the steel."]'::jsonb, 1, 'In series, so the same flow rate passes through every element and the losses add. This course sets the surface loss to zero.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 2, 'Why does the hydrostatic column not appear in the pump pressure?', '["Because the mud in the string and in the annulus weigh the same and cancel exactly.", "Because it is added separately.", "Because the pump is at surface, where the hydrostatic pressure is zero and nothing has accumulated yet.", "Because the model works in gauge pressure rather than absolute, which removes the static term by definition."]'::jsonb, 0, 'That cancellation is why a pump pressure is tens of bar rather than the hundreds of hydrostatic head, and it fails during a kick.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 3, 'Which of the three losses is not a friction loss?', '["The annulus, which is gravitational.", "The pipe, which is dominated by the entry and exit losses at each string component rather than by wall friction.", "The bit, which is inertial.", "None of them: all three are friction against a wall, computed with the same friction factor correlation."]'::jsonb, 2, 'That is why it has a different exponent and why its share behaves differently from the other two.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 4, 'What happens to the annulus share as the flow rate rises?', '["It rises, being the gentlest law.", "It stays constant at about an eighth, because all three losses scale with the same flow rate.", "It rises to a maximum around 0.025 m3/s and then falls as the pipe becomes fully turbulent.", "It falls sharply, from about a fifth to under a tenth over the course''s range."]'::jsonb, 3, 'It is the gentlest law, with an exponent below one, so the other two grow faster and its share shrinks.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 5, 'What are the three exponents against flow rate?', '["About 0.75 for the annulus, about 1.72 for the pipe, exactly 2 for the bit.", "All three are exactly 2.", "About 1 for the annulus, about 1.8 for the pipe and about 2 for the bit, matching laminar, turbulent and inertial.", "They vary with the mud, so no single set of three numbers applies across the four cases in this course."]'::jsonb, 0, 'Laminar annulus with a shear-thinning fluid, turbulent pipe, inertial bit. Those three explain every share in the course.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 6, 'Is the pump pressure a system property or a well property?', '["A well property.", "A system property: change the string, the bit or the mud and it changes.", "Both: it depends on the string and the bit through the friction and on the formation through the hydrostatic head.", "Neither: it is a property of the pump, which delivers whatever pressure its liner size and speed permit."]'::jsonb, 1, 'Change the formation and it does not move at all. That is the opposite of the equivalent circulating density.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 7, 'What is the largest lever on pump pressure?', '["The nozzle area.", "The mud weight, since the density appears linearly in every one of the three loss terms simultaneously.", "The flow rate.", "The depth, since both the pipe and the annulus losses are proportional to the length of the flow path."]'::jsonb, 2, 'Then the string''s bore, then the mud, then the nozzles, then depth. The first two are usually fixed by the time the question is asked.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 8, 'What does a pump pressure changing with no input change tell you?', '["The formation pressure changed.", "The flow rate drifted, since the pump''s output falls as its liners wear and the volumetric efficiency drops.", "The equivalent circulating density changed, which is transmitted back to the pump through the annulus.", "Something changed in the string or in the mud, because the formation does not enter it."]'::jsonb, 3, 'A washout, a plugged nozzle, a bit balling up, or a mud property drifting. That is why measured against computed is a diagnostic.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 9, 'How many values does the oracle comparison check, and to what tolerance?', '["Over a hundred, and the goldens ask for better than one part in a million.", "Four, one per case.", "Eighteen, matching the graded capstone fields, which are the only values a learner will ever reproduce.", "Three per case, one for each of the flow rates the lessons run at."]'::jsonb, 0, 'The engine achieves better than the asked-for tolerance on every one of them.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 10, 'Which part of the oracle comparison agrees at machine precision?', '["The pump pressures.", "The equivalent circulating density, since it is a simple division and involves no accumulated arithmetic at all.", "The surge and swab pressures.", "The rheology fits, which are exact closed-form expressions in the four dial readings."]'::jsonb, 2, 'The rheology fits agree to about 1e-10, which is the rounding of the published nine-decimal values rather than a real gap.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 11, 'Why is the pump pressure the largest disagreement in the comparison?', '["Because it is the largest number.", "Because it is the longest chain: a fit, a local power law per element, a Reynolds number, a friction factor, a sum.", "Because it includes the bit term, which is the only inertial loss and is computed differently in the two codes.", "Because the two implementations blend the laminar and turbulent laws over different Reynolds number bands."]'::jsonb, 1, 'Each step carries a rounding and they accumulate. About 1e-7 over that chain is what a long calculation looks like.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 12, 'What does agreement with the oracle prove?', '["That the model describes a real well.", "That the method specification is correct, since two independent derivations of it arrived at the same result.", "That the friction factor correlations are valid, since both implementations reproduce them within the tolerance.", "That two people reading the same specification wrote code producing the same numbers."]'::jsonb, 3, 'Both share every modelling choice by construction, so agreeing says nothing at all about whether those choices are right.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 13, 'How does this course''s oracle result compare with the torque and drag course''s?', '["This one agrees everywhere; that one had a real disagreement to explain.", "Both had disagreements of similar size.", "This one disagrees more, because the hydraulics chain is longer and accumulates more floating-point rounding.", "Neither has an oracle: both courses are checked against published field measurements instead."]'::jsonb, 0, 'The disagreement is the more instructive of the two, because it forces the question of which implementation is right.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 14, 'What would the equivalent of the vertical well be for this course?', '["The slant well at zero flow rate.", "The light mud, whose lower density and thinner rheology make the pressure loss simple enough to compute by hand.", "A degenerate case with a closed-form answer, and there is none here.", "The bit pressure drop, which has a closed form and is exactly reproduced by both implementations."]'::jsonb, 2, 'The bit is a closed form and both implementations compute it identically, so it settles nothing. Zero flow gives zero loss.'),
  ('hydraulics', 'beginner', 'module', 'm05-pump-pressure', 15, 'What does the surface loss represent, and what is it set to here?', '["The pump''s own internal losses.", "The standpipe, hose, swivel and kelly, and it is set to zero.", "The loss between the shakers and the pit, which is normally negligible and is therefore ignored by convention.", "The pressure at the top of the annulus, which is atmospheric on a well without a rotating control device."]'::jsonb, 1, 'Setting it to zero makes the three named losses add to the total exactly, which is a free check on every run.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 1, 'After the Associate tier, what work can you honestly say you are able to do?', '["Design a mud programme from scratch.", "Say how fast the cuttings are travelling and what flow rate would be needed to move them faster.", "Compute what the pump will read, and say which part of it the formation never sees.", "Say how fast the string may be tripped without fracturing the formation or bringing in a kick."]'::jsonb, 2, 'The other two are the Professional and Expert tiers, in that order, over the same four fixtures.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 2, 'If the Associate tier had one line, what would it be?', '["A pump pressure is three losses in series, each with its own exponent, and only one reaches the rock.", "A pump pressure is the hydrostatic head.", "A mud is four dial readings, and the three models fitted to them agree where it matters and differ where it does not.", "The equivalent circulating density is the mud weight plus the annulus loss over the true vertical depth."]'::jsonb, 0, 'Both of the wrong answers are true statements from this tier. The claim is the structure that holds them together.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Which two conversions turn dial readings into a curve?', '["Both are one to one.", "The rpm is the shear rate directly, and the dial degree converts to pascals through the instrument''s spring constant.", "The rpm converts through the cylinder''s radius, and the dial converts through the mud''s own density.", "1.70233 per second per rpm, and 0.51040356094 pascals per dial degree."]'::jsonb, 3, 'The dial constant is a geometry factor of 1.066 times the conversion from pounds force per hundred square feet to pascals.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Which model reproduces the 600 and 300 rpm readings exactly?', '["Herschel-Bulkley alone.", "Both the power law and the Bingham plastic, being two-parameter fits to those two points.", "The power law alone, since Bingham is fitted to the 300 and 6 rpm readings to capture the yield stress.", "None of them, because all three are least-squares fits to all four of the readings available."]'::jsonb, 1, 'Herschel-Bulkley has three parameters and four points, so it reproduces none of them exactly and misses all four by a little.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 5, 'Where do the three rheology models matter most?', '["In the pipe, where the stresses are largest.", "At the bit, where the jet velocity depends on the apparent viscosity at very high shear rate.", "In the annulus, where the shear rates are low and the models differ by a factor of ten.", "Nowhere, since the engine uses Herschel-Bulkley throughout and the other two are shown only for comparison."]'::jsonb, 2, 'So the model choice barely moves the pump pressure and moves the number the formation feels.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 6, 'Three losses, three different responses to opening the pump up. Name them.', '["About 0.75 laminar annulus, about 1.72 turbulent pipe, exactly 2 inertial bit.", "All three are close to 1.8.", "About 1 for the annulus, about 2 for the pipe and about 2 for the bit, matching laminar, turbulent and inertial.", "They cannot be stated generally, because each depends on the mud''s flow behaviour index at the local shear rate."]'::jsonb, 0, 'The annulus''s exponent is below one because it is laminar AND the mud is shear thinning, and it inherits n directly.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 7, 'Why is the annulus''s sub-linear exponent encouraging?', '["Because it makes the pump smaller.", "Because extra flow rate is cheap at the formation and expensive at the pump.", "Because it means the annulus loss falls as the rate rises, so a faster circulation is safer than a slow one.", "Because it makes the equivalent circulating density independent of the flow rate above a threshold value."]'::jsonb, 1, 'Doubling the rate raises the equivalent circulating density by much less than double, which is why raising the rate is usually possible.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 8, 'What does the capstone run on?', '["The same conditions the lessons use.", "The light mud at 0.035 m3/s on the horizontal well, which is the most demanding combination in the fixture set.", "A synthetic mud with a Newtonian rheology, so that the arithmetic can be checked entirely by hand.", "A mud, a flow rate and a well the lessons do not use together."]'::jsonb, 3, 'The new mud has dial readings of 52, 33, 6 and 5 at a density of 1320, and the flow rate is 0.030 m3/s.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Why does the capstone use a different mud from the lessons?', '["Because the lesson muds are proprietary.", "Because the two lesson muds are too similar to distinguish, so a third was needed to make the grading meaningful.", "So that every graded number is one you have to produce rather than one a lesson printed.", "Because the goldens do not include the lesson muds at 0.030 m3/s, so the capstone had to use a different one."]'::jsonb, 2, 'It is also a real exercise: a new mud has been mixed and the hydraulics have to be rerun on it.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 10, 'What is the free check available on the capstone''s four pressures?', '["The pump pressure equals the sum of the other three, because the surface loss is zero.", "The bit share should be 65 percent.", "The annulus loss should be about a fifth of the pipe loss, which is the ratio the lessons found on both muds.", "The equivalent circulating density should equal the mud weight plus five percent, which is typical for a well of this depth."]'::jsonb, 0, 'If they do not add, one of the four is wrong, and that costs one subtraction to find out.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Which two capstone fields need no well at all?', '["The pipe loss and the annulus loss.", "The power-law n and the Herschel-Bulkley yield stress.", "The bit pressure and the pump pressure, since both follow from the flow rate and the nozzle area alone.", "None: every field needs the survey, because the pressure losses depend on the true vertical depth."]'::jsonb, 1, 'They come from the four dial readings and the two conversion constants, and getting them right confirms the rheology first.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 12, 'What is the trap between the two yield numbers?', '["They are the same number.", "The Bingham yield point is in pounds force per hundred square feet and the Herschel-Bulkley one is in pascals.", "The Herschel-Bulkley yield is larger, because it is fitted to a low-rate reading rather than extrapolated.", "The Bingham yield point is more than twice the Herschel-Bulkley yield stress, and both are in pascals."]'::jsonb, 3, 'The units do not distinguish them, and the Bingham value is an extrapolation from two high-rate readings.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Which single idea does the whole next tier build on?', '["That the bit is a square law.", "That the collars'' bore dominates the pipe loss, which is two thirds of the pump pressure on this system.", "That only the annulus loss reaches the formation, and it is the smallest of the three.", "That the power law understates the low-rate stress by a factor of five, which is the range the annulus runs at."]'::jsonb, 2, 'All three are true. The first is the one the whole next tier is built on.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 14, 'A colleague treats a high standpipe reading as a hard-pushed well. What is wrong?', '["How hard the well is being pushed.", "How much power the pump is delivering.", "How restrictive the string is, which is exactly what two thirds of it represents on this system.", "The total friction in the circulating system, which is the sum of the three losses it is made of."]'::jsonb, 0, 'A well with a restrictive string has a high pump pressure and may have a low equivalent circulating density.'),
  ('hydraulics', 'beginner', 'module', 'm06-the-associate-reading', 15, 'How many jobs does the mud have, and which one opposes the others?', '["Three, and cooling the bit opposes them.", "Four, and not breaking the formation opposes the other three.", "Four, and holding the hole up opposes the other three, since a heavier mud is harder to pump and clean with.", "Five, including transmitting telemetry, which opposes the others by requiring a specific viscosity range."]'::jsonb, 1, 'Holding the hole up wants density, which is on the same side as not letting formation fluid in. Not fracturing wants less of it.'),
  ('hydraulics', 'beginner', 'final', null, 1, 'A report quotes a pressure of 12 MPa with no other qualifier. What do you ask?', '["What units it is in.", "Which pressure: pump, bit, annulus or equivalent circulating density.", "What depth it applies to, since a pressure without a depth cannot be converted to an equivalent mud weight.", "What flow rate it was computed at, which is the only input that moves it and is often left out."]'::jsonb, 1, 'The flow rate and the depth both matter and are secondary. Naming the pressure is what makes the number identifiable at all.'),
  ('hydraulics', 'beginner', 'final', null, 2, 'The standpipe pressure rises sharply with no change to the flow rate. What are the two candidates?', '["A plugged nozzle or a pack-off in the annulus.", "A washout or a thinning mud.", "A rise in the equivalent circulating density, which is transmitted back to the pump through the annulus.", "A rise in the formation pressure, which increases the back pressure the pump has to work against."]'::jsonb, 0, 'A pack-off also raises the torque and drag. A washout LOWERS the pressure, and the formation does not enter it at all.'),
  ('hydraulics', 'beginner', 'final', null, 3, 'A mud engineer reports a PV of 26 and a YP of 12. What have they given you?', '["A Herschel-Bulkley fit.", "A power-law fit, expressed in the consistency index and the flow behaviour index rather than in n and K.", "A Bingham fit to the 600 and 300 rpm readings, in field units.", "The gel strengths at 10 seconds and 10 minutes, which are the two standard low-rate measurements."]'::jsonb, 2, 'PV is theta600 less theta300 and YP is theta300 less PV. Both are computed by subtraction from the two high-rate readings.'),
  ('hydraulics', 'beginner', 'final', null, 4, 'A hydraulics package uses the power law and reports a comfortable ECD. What is your concern?', '["The power law is too conservative.", "The power law is fitted to the low-rate readings, which are the least reliable ones on a Fann viscometer.", "Nothing: the annulus runs at high shear rate, where all three models agree to four significant figures.", "The power law has no yield stress and understates the low-rate stress by a factor of five."]'::jsonb, 3, 'The annulus runs at LOW shear rate, which is exactly where the models diverge, and understating the ECD is the unsafe direction.'),
  ('hydraulics', 'beginner', 'final', null, 5, 'You need to lower the pump pressure without changing the flow rate. What do you do first?', '["Open the nozzles up, which is free and touches nothing else.", "Thin the mud.", "Reduce the mud weight, which lowers every one of the three losses proportionally and is the largest single lever.", "Reduce the depth by picking up off bottom, which shortens the flow path and reduces both the pipe and annulus losses."]'::jsonb, 0, 'Thinning the mud works and it also changes the equivalent circulating density and the cleaning. The nozzle touches only the pump.'),
  ('hydraulics', 'beginner', 'final', null, 6, 'Somebody proposes tightening the nozzles to reach a 65 percent bit share on this system. What happens?', '["The bit hydraulics improve at no cost.", "The pump pressure goes far beyond anything a rig would supply.", "The equivalent circulating density rises, because the extra bit pressure has to be pushed through the annulus.", "Nothing: the split is fixed by the string''s geometry and the nozzles cannot change it."]'::jsonb, 1, 'The collars'' bore is consuming so much pressure that there is little left, and the fix is a bigger bore rather than smaller nozzles.'),
  ('hydraulics', 'beginner', 'final', null, 7, 'Two hydraulics packages give ECDs 8 percent apart on identical inputs. What is the likeliest cause?', '["One of them has a coding defect.", "Different mud density inputs, which enter every term linearly and would produce exactly that size of difference.", "Different modelling conventions, most likely the laminar-turbulent blend.", "Different survey interpolation, which changes the true vertical depth and therefore the equivalent circulating density."]'::jsonb, 2, 'Four of the seven points in a hydraulics method specification are conventions, and the annulus often sits inside the blend band.'),
  ('hydraulics', 'beginner', 'final', null, 8, 'Where in this course''s well is the annular velocity lowest?', '["Around the collars in open hole.", "At total depth, where the annulus has the most cuttings in it and the effective flow area is therefore smallest.", "It is the same everywhere, because the flow rate is constant and the annulus is a single continuous path.", "In the cased section, which is the widest annulus."]'::jsonb, 3, 'Velocity is flow rate over area, so the widest annulus is the slowest, and it is the shallowest part of the hole.'),
  ('hydraulics', 'beginner', 'final', null, 9, 'A driller asks why the standpipe pressure creeps up all through a section. What do you say?', '["Every metre of hole adds pipe and annulus length, and both losses are proportional to length.", "The mud is thickening with solids.", "The bit is wearing, which enlarges the nozzles and raises the pressure needed to push mud through them.", "The equivalent circulating density is rising, which the pump has to overcome as an additional back pressure."]'::jsonb, 0, 'A worn nozzle is LARGER, which lowers the pressure. Solids do thicken the mud and that is a slower effect than the depth one.'),
  ('hydraulics', 'beginner', 'final', null, 10, 'The pump pressure falls suddenly with no other change. What is it?', '["A plugged nozzle.", "A washout: a hole in the string giving the mud a shortcut.", "A pack-off, which reduces the flow area and therefore the volume the pump has to move at a given rate.", "A rise in the mud weight, which raises the hydrostatic head in the annulus and offsets part of the friction."]'::jsonb, 1, 'The hydrostatic heads cancel, so the mud weight does not enter the pump pressure that way. A plugged nozzle RAISES it.'),
  ('hydraulics', 'beginner', 'final', null, 11, 'Which loss is proportional to the flow rate squared, exactly?', '["The pipe, being turbulent.", "The annulus, because the flow area is fixed and the pressure loss depends on the velocity head at that area.", "The bit, because it is inertial and has no viscosity in it.", "All three, because pressure loss is proportional to velocity squared in the general element expression."]'::jsonb, 2, 'The general expression has v squared in it and the friction factor also depends on velocity, which is why the other two exponents are not two.'),
  ('hydraulics', 'beginner', 'final', null, 12, 'You are told the annulus is laminar and the pipe is turbulent. What follows?', '["The pump pressure rises much faster with flow rate than the ECD does.", "Both rise at the same rate.", "The equivalent circulating density rises faster, because a laminar annulus has a higher friction factor.", "The bit share falls with flow rate, since the turbulent pipe loss grows faster than the bit''s square law."]'::jsonb, 0, 'The bit''s exponent is exactly two and the pipe''s is about 1.72, so the bit share rises rather than falls.'),
  ('hydraulics', 'beginner', 'final', null, 13, 'Why is the drill collars'' bore a hydraulics decision?', '["Because it sets the annular clearance.", "Because a small bore raises the shear rate, which thins the mud and lowers the friction factor there.", "Because the collars are the heaviest component and their bore determines how much mud they displace.", "Because it carries roughly four times the drill pipe''s velocity and velocity enters squared."]'::jsonb, 3, 'The thinning is real and it does not offset the velocity squared. The collars are five percent of the length and a large share of the loss.'),
  ('hydraulics', 'beginner', 'final', null, 14, 'A learner computes an ECD using measured depth instead of true vertical depth. Which way is the error?', '["Too high, which is conservative.", "There is no error on a vertical well and the sign depends on the inclination profile on a deviated one.", "The ECD comes out too low, which is the unsafe direction.", "The error affects only the profile shape and not the value at total depth, where the two depths converge."]'::jsonb, 2, 'Measured depth is always at least true vertical depth, so dividing by it gives a smaller uplift, and on a horizontal well much smaller.'),
  ('hydraulics', 'beginner', 'final', null, 15, 'Which single input would you check first if a computed pump pressure looked wrong?', '["The nozzle area.", "The string''s inside diameters, since two thirds of it is the pipe loss.", "The mud density, which appears linearly in every term and is measured at the shakers every tour.", "The survey, since the pipe and annulus lengths both come from it and both losses are proportional to length."]'::jsonb, 1, 'All three are worth checking. The bores dominate and they are also the input most often entered from a nominal size rather than a measurement.'),
  ('hydraulics', 'beginner', 'final', null, 16, 'The engine warns that the hole geometry does not cover the full string. What does that do?', '["Skips those annulus spans entirely, so the annulus loss is understated by an unknown amount.", "Applies zero friction there.", "Extends the last geometry section to cover them, which is conservative because the deepest section is the tightest.", "Refuses to compute the equivalent circulating density while still returning the pump pressure."]'::jsonb, 0, 'Zero friction would at least be a defined answer. Skipping means the length contributes nothing at all.'),
  ('hydraulics', 'beginner', 'final', null, 17, 'What is the practical consequence of the bit being the only exact square law?', '["The bit is the largest loss.", "The bit pressure is independent of the mud, so it can be computed before the mud programme is finalised.", "The bit''s contribution can be computed analytically from a measured pump pressure.", "The bit''s share is constant, so a single measurement at one flow rate characterises the whole system."]'::jsonb, 2, 'The bit pressure IS proportional to density, so the mud enters it. Pumping at two rates and taking the difference is how the split is estimated on a rig.'),
  ('hydraulics', 'beginner', 'final', null, 18, 'Which two of the four mud jobs want more flow rate?', '["Holding the hole up and not fracturing.", "Carrying cuttings and holding the hole up, since a faster annulus reduces the time cuttings spend in the hole.", "Cleaning the bit and not fracturing, since a faster jet clears the bottom and reduces the pressure needed to drill.", "Carrying cuttings, and cleaning and cooling the bit."]'::jsonb, 3, 'Holding the hole up wants density rather than rate, and not fracturing wants less of both.'),
  ('hydraulics', 'beginner', 'final', null, 19, 'What does an apparent viscosity of 0.58 Pa.s at 5 per second and 0.032 at 1022 tell you?', '["The mud is Newtonian.", "The mud is strongly shear thinning, by a factor of about eighteen across that range.", "The mud has a very high plastic viscosity, since the apparent viscosity at high rate approaches it asymptotically.", "The measurement is unreliable, because a factor of eighteen is far beyond what a drilling mud exhibits."]'::jsonb, 1, 'That is the property that makes a drilling mud work: thick in the annulus where it carries, thin in the pipe where it is pumped.'),
  ('hydraulics', 'beginner', 'final', null, 20, 'A pump pressure calculation gives 40 MPa at a proposed flow rate. What do you conclude?', '["The mud is too thick.", "The equivalent circulating density will exceed the fracture gradient, since the two are proportional.", "The flow rate is not achievable on any normal rig.", "The calculation is wrong, since a pump pressure of that size would exceed the string''s burst rating."]'::jsonb, 2, 'The ECD is not proportional to the pump pressure at all: the annulus is under a tenth of it at high rate.'),
  ('hydraulics', 'beginner', 'final', null, 21, 'Which of the three losses would you reduce to lower the ECD?', '["The annulus, and only the annulus.", "The pipe, being the largest.", "The bit, since it is the loss that occurs closest to the formation and therefore reaches it most directly.", "All three in proportion, since they add to the pump pressure that drives the whole circulating system."]'::jsonb, 0, 'The pipe and the bit are inside the string. Reducing them lowers the pump pressure and does not touch the formation.'),
  ('hydraulics', 'beginner', 'final', null, 22, 'What separates the yield stress in Herschel-Bulkley from a gel strength?', '["Nothing, they are the same.", "Units: the yield is in pascals and the gel strength is in pounds force per hundred square feet.", "The instrument: the yield is measured on a Fann viscometer and the gel on a shearometer.", "Time: the yield has none in it and the gel grows with time at rest."]'::jsonb, 3, 'Both are measured on the same instrument in the same units. The break-circulation pressure depends on the gel and is uncomputable here.'),
  ('hydraulics', 'beginner', 'final', null, 23, 'The engine reports a laminar label on every annulus element and turbulent inside the pipe. Is that expected?', '["No, it should be the reverse.", "Yes: the annulus is wide and slow and the pipe is narrow and fast.", "Only for the heavy mud; the light mud is thin enough that its annulus is turbulent at ordinary flow rates.", "Only at low flow rates; above about 0.03 m3/s the annulus becomes turbulent on both muds."]'::jsonb, 1, 'It also explains the two exponents: the annulus inherits the mud''s shear-thinning index and the pipe follows a turbulent correlation.'),
  ('hydraulics', 'beginner', 'final', null, 24, 'How would you estimate the system pressure loss on a rig without a model?', '["Read the standpipe gauge at one rate.", "Circulate with the bit off bottom and no nozzles, which removes the bit term and leaves the system loss directly.", "Pump at two rates, take the difference, and subtract the bit''s analytic contribution.", "Take the pump pressure and multiply by the published typical bit share for the hole size being drilled."]'::jsonb, 2, 'The bit''s square law is exactly known, so it can be removed analytically. Everything else has to be measured.'),
  ('hydraulics', 'beginner', 'final', null, 25, 'Why does a hydraulics answer need its method specification quoted with it?', '["Because four of the seven points in it are conventions rather than derivations.", "Because the standard requires it.", "Because the specification determines which of the three rheology models the calculation used at each element.", "Because two implementations of the same specification will disagree by a few percent in the transition region."]'::jsonb, 0, 'Two implementations of the SAME specification agree to better than 1e-6. Two of different specifications will not.'),
  ('hydraulics', 'beginner', 'final', null, 26, 'A well is drilled with a 17 and a half inch bit and needs an enormous flow rate. Why?', '["The bit has more nozzles.", "The annulus is very wide, so a given rate produces a low velocity.", "The cuttings are larger in a big hole, so their slip velocity is higher and more flow is needed to overcome it.", "The rate of penetration is higher in a big hole, so the cuttings feed rate is proportionally greater."]'::jsonb, 1, 'Both of the wrong answers contribute. The dominant effect is that velocity is flow rate over area and the area is large.'),
  ('hydraulics', 'beginner', 'final', null, 27, 'Which output is a profile rather than a single number?', '["The pump pressure.", "The bit pressure drop, which varies along the nozzle as the mud accelerates through the contraction.", "The transport ratio, which the engine reports as a single worst value across the annulus.", "The equivalent circulating density."]'::jsonb, 3, 'The transport ratio is also reported per interval, and the summary quotes the worst. The ECD''s whole shape is the useful output.'),
  ('hydraulics', 'beginner', 'final', null, 28, 'What does the discharge coefficient of 0.95 do to the bit pressure?', '["Lowers it by five percent.", "Raises it by five percent, since it multiplies the jet velocity and the pressure follows the velocity linearly.", "Raises it by about ten percent over an ideal nozzle, because it appears squared.", "Nothing: it cancels between the pressure and the velocity when the two are computed from the same flow rate."]'::jsonb, 2, 'It is an efficiency: a real nozzle contracts the flow slightly and does not convert all the pressure into jet velocity.'),
  ('hydraulics', 'beginner', 'final', null, 29, 'Which is a system property and which is a formation property?', '["The pump pressure is a system property; the equivalent circulating density is a formation one.", "Both are formation properties.", "The pump pressure is a formation property because it includes the hydrostatic head, and the ECD is a system one.", "Both are system properties, since neither depends on anything about the rock being drilled."]'::jsonb, 0, 'The ECD is a system property too in the sense that the system produces it. What makes it a formation property is that the formation feels it.'),
  ('hydraulics', 'beginner', 'final', null, 30, 'A learner uses the Bingham fit for a pressure calculation. Which way is the ECD wrong?', '["Too low.", "Too high, because Bingham overstates the low-rate stress.", "It depends on the flow rate: too high at low rates where the annulus is laminar, too low at high rates.", "It is not wrong, since the engine converts any of the three fits to the same local power law before computing."]'::jsonb, 1, 'The conversion is done on whichever model is supplied, so the choice propagates all the way through.'),
  ('hydraulics', 'beginner', 'final', null, 31, 'The four mud jobs conflict. Which pair conflicts most directly?', '["Cooling the bit and holding the hole up.", "Holding the hole up and carrying cuttings, since a denser mud is harder to circulate at a useful rate.", "Carrying cuttings and not fracturing, which pull the flow rate in opposite directions.", "Cleaning the bit and cooling it, since a fast jet cools well and a slow one cleans the cutting structure better."]'::jsonb, 2, 'That is the whole hydraulics trade and it is what the Professional tier is about.'),
  ('hydraulics', 'beginner', 'final', null, 32, 'What is the shear rate range in the annulus, roughly?', '["Thousands per second.", "Around 511 per second, which is why the 300 rpm dial reading is the one the annulus calculation should use.", "It cannot be estimated, because the shear rate varies across the annulus from the pipe wall to the hole wall.", "Tens per second."]'::jsonb, 3, 'Inside the pipe it is hundreds to thousands, which is where the three models agree. The annulus is where they diverge.'),
  ('hydraulics', 'beginner', 'final', null, 33, 'A hydraulics model is described as steady state. What does that exclude?', '["Starting and stopping the pumps, and everything else that is changing.", "Turbulent flow.", "Any variation with depth, since a steady state means the same conditions everywhere along the flow path.", "The cuttings calculation, which needs a rate of penetration and is therefore inherently time dependent."]'::jsonb, 0, 'The cuttings calculation is a steady state too: a constant feed and a constant carrying rate.'),
  ('hydraulics', 'beginner', 'final', null, 34, 'Which two conversions would a learner most easily get wrong?', '["The density and the depth.", "The rpm-to-shear-rate constant and the discharge coefficient, both of which are dimensionless multipliers.", "The dial-to-pascal constant and the total flow area in SI.", "The flow rate in cubic metres per second and the pressure in pascals, which are both large numbers in SI."]'::jsonb, 2, 'Nozzle sizes are in thirty-seconds of an inch and areas are in square inches, and a factor of a thousand in the wear-factor style is the classic error.'),
  ('hydraulics', 'beginner', 'final', null, 35, 'What does the engine do with a flow element that has zero velocity?', '["Refuses to compute.", "Returns a zero pressure loss with a static regime label.", "Applies the laminar law, which gives an infinite friction factor at zero Reynolds number and a zero product.", "Applies the yield stress alone, since a fluid with a yield does not flow at all below its yield stress."]'::jsonb, 1, 'The static label is worth knowing about, because it is the only regime that does not correspond to a friction factor law.'),
  ('hydraulics', 'beginner', 'final', null, 36, 'Which of these would NOT change the pump pressure?', '["A change in the mud weight.", "A change in the nozzle total flow area, which moves the bit''s contribution without touching the other two losses.", "A change in the flow rate, which is the largest single lever on it in the whole calculation.", "A change in the formation being drilled."]'::jsonb, 3, 'That is the definition of a system property, and it is what makes measured against computed a diagnostic.'),
  ('hydraulics', 'beginner', 'final', null, 37, 'What is a good reason to run the oracle check before trusting a hydraulics answer?', '["It exercises the whole calculation path against a value somebody else computed.", "It validates the physics.", "It confirms the mud rheology, which is the input most likely to have been entered from a stale mud check.", "It bounds the discretisation error, which is the largest source of uncertainty in a long flow path."]'::jsonb, 0, 'There is no discretisation in this calculation: the elements come from the geometry rather than from a grid.'),
  ('hydraulics', 'beginner', 'final', null, 38, 'How does the annulus loss''s share change from 0.015 to 0.035 m3/s on this well?', '["It rises from a tenth to a fifth.", "It stays at about an eighth, since all three losses scale together with the flow rate.", "It falls from about a fifth to under a tenth.", "It cannot be said without the mud, because the two muds have different flow behaviour indices."]'::jsonb, 2, 'The annulus has the gentlest exponent, so the other two grow faster and its share shrinks even though its value rises.'),
  ('hydraulics', 'beginner', 'final', null, 39, 'A colleague says a high pump pressure means the well is being pushed hard. Correct them.', '["A high pump pressure is dangerous.", "Most of it is inside the string, and the formation sees only the annulus loss.", "A high pump pressure means the flow rate is high, which is what the formation actually responds to.", "A high pump pressure means the mud is thick, which raises the equivalent circulating density proportionally."]'::jsonb, 1, 'On this system two thirds of the pump pressure is spent getting the mud down the inside of the string.'),
  ('hydraulics', 'beginner', 'final', null, 40, 'What is the free arithmetic check on any hydraulics run in this course?', '["The bit share is 65 percent.", "The equivalent circulating density equals the mud weight times one plus the bit share.", "The annulus loss equals the pipe loss divided by the ratio of the two characteristic diameters.", "The three losses add to the pump pressure exactly, because the surface loss is zero."]'::jsonb, 3, 'It costs one subtraction and it catches a surprising number of setup errors.'),
  ('hydraulics', 'beginner', 'final', null, 41, 'What would you tell a mud engineer who wants to thin the mud to lower the ECD?', '["It will not affect the ECD.", "It will raise the ECD, because a thinner mud is more likely to be turbulent in the annulus and turbulent loss is higher.", "It will work, and it will also make the cuttings harder to carry.", "It will lower the ECD and improve the cleaning, since a thinner mud has a lower slip velocity for the cuttings."]'::jsonb, 2, 'A thinner mud has a HIGHER slip velocity, because it resists a falling chip less. Both effects go the wrong way for cleaning.'),
  ('hydraulics', 'beginner', 'final', null, 42, 'Which lesson from this tier would you give a driller in one sentence?', '["Compare the standpipe gauge against a computed value often, so a departure is visible immediately.", "Always run the largest nozzles available.", "Keep the flow rate as high as the pump allows, since the annulus is the cheapest of the three losses to buy.", "Use the Bingham model, since PV and YP are what the mud report gives and the fit is exact at both readings."]'::jsonb, 0, 'It is the same habit the torque and drag course asks for with hookloads, and it is what makes a change detectable.');
